PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?maternalGrandmother ?grandmotherName WHERE {
  dbr:Princess_Maria_Ferdinanda_of_Saxony dbp:mother ?mother .
  ?mother dbp:mother ?maternalGrandmother .
  OPTIONAL { ?maternalGrandmother rdfs:label ?grandmotherName .
             FILTER (lang(?grandmotherName) = "en") }
}
LIMIT 100

